// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette as C} from "../src/Roulette.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an arbitrary caller and two timestamps (represented via vm.warp calls)
    function testFuzz_property(address caller, uint256 t1, uint256 t2) public {
        caller = address(uint160(bound(uint256(uint160(caller)), 0xffff + 1, type(uint160).max)));
        vm.assume(caller.code.length == 0 && caller != address(this) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        // keep caller as a regular EOA
        vm.assume(caller != address(0));

        // bound the timestamps to a reasonable range to avoid overflow of block.timestamp semantics
        t1 = bound(t1, 1, type(uint32).max);
        t2 = bound(t2, 1, type(uint32).max);

        // ensure we send exactly 10 ether as required by the contract
        uint256 amount = 10 ether;
        vm.deal(caller, amount);

        // First call at time t1
        vm.warp(t1);
        vm.prank(caller);
        // call fallback with 10 ether
        (bool ok1, ) = address(c).call{value: amount}("");
        // require first call succeeded for admissible scenarios
        // if it reverts, then pastBlockTime was not updated; that is acceptable, but to exercise the property we continue

        // read pastBlockTime after first call
        uint256 first = c.pastBlockTime();

        // Second call at time t2
        vm.warp(t2);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: amount}("");

        uint256 second = c.pastBlockTime();

        // General rule: in the reference contract, whenever a fallback call completes successfully and updates pastBlockTime,
        // the stored pastBlockTime must be strictly increasing relative to any previous stored value (i.e., second > first) when t2 <= t1 the update must NOT occur.
        // We assert the universal-safe condition: if t2 <= t1 then pastBlockTime must not decrease or be set to a value <= first.
        // This is a single assertTrue reading c's public getter which the reference satisfies for all inputs,
        // and the mutant (which removed the timestamp require) will allow second <= first for some fuzzed inputs.

        if (t2 <= t1) {
            // If the second time is not strictly greater, the reference requires that pastBlockTime does not become greater/equal improperly.
            // Concretely: when t2 <= t1, second must be <= first only if the second call reverted; but if second call succeeded it must not have updated to a non-greater value.
            // To capture a single simple universal assertion that the reference enforces: after the second call, pastBlockTime must be >= first only if t2 > first (i.e., time advanced). Simpler: when t2 <= first, second must be <= first only if ok2 is false OR second == first (no improper increase). The mutant may set second == t2 which could be <= first and thus violate the strict-increase expectation if ok2 is true. We'll assert that if the second call succeeded then second > first must hold when t2 > first; but here t2 <= t1 so we assert that if ok2 then second >= first. This catches the mutant which sets pastBlockTime to a non-greater timestamp.
            // For clarity and to remain a single assertion on c's getter we assert:
            assertTrue(!(ok2 && second <= first));
        } else {
            // When t2 > t1, it's acceptable that pastBlockTime increases; require monotonicity: second >= first
            assertTrue(second >= first);
        }
    }
}
